/**
 * Audio contract (GDD 2.13). Types only — shared by the audio engine and by every gameplay system that wants a
 * sound. Gameplay code never touches Web Audio directly: it emits the events below (or calls the 'audio'
 * service), so the game still runs silently before the audio is unlocked or when it is unavailable.
 */

/** One-shot effects. Recipes for every id live in src/audio/sfx/ (generated by code on load). */
export type SfxId =
  // footsteps per surface
  | 'step_dirt' | 'step_stone' | 'step_mud' | 'step_wood' | 'step_grass' | 'step_water'
  // the Burden and the Cross
  | 'burden_creak' | 'burden_huff' | 'burden_boing' | 'rope_snap' | 'sack_roll' | 'tomb_thoom'
  | 'joy_note' | 'sparkle'
  // Roll, Promises, waystones
  | 'roll_unroll' | 'promise_chime' | 'waystone_save'
  // world interactions
  | 'knock' | 'arrow_whistle' | 'arrow_thunk' | 'bonk' | 'stars' | 'lion_roar' | 'chain_rattle'
  | 'cage_clank' | 'gate_grind' | 'net_drop' | 'mud_slurp' | 'splash' | 'jump' | 'land'
  // combat
  | 'sword_whoosh' | 'sword_hit' | 'shield_clang' | 'perfect_block' | 'dart_whoosh' | 'prayer_swell'
  | 'shadow_squeak'
  // weather and creatures
  | 'thunder' | 'frog_croak' | 'sheep_baa' | 'snore' | 'bells' | 'bird_chirp'
  // UI
  | 'ui_click' | 'ui_open' | 'ui_close' | 'ui_toast' | 'ui_choice';

/** Looping beds handled by the ambience system (positional where an emitter position is given). */
export type AmbienceId =
  | 'town' | 'bog' | 'hills' | 'wind' | 'candle' | 'fair' | 'river' | 'birdsong' | 'rain' | 'valley' | 'night'
  | 'dungeon' | 'meadow';

/** Songs (GDD 2.13 themes). Note data lives in content/music/themes.ts — ORIGINAL melodies only. */
export type SongId =
  | 'pilgrim'        // main theme, hopeful
  | 'burden'         // slow, low, 3 heavy notes
  | 'wiseman'        // waltz: charming, slightly silly
  | 'interpreter'    // music box
  | 'apollyon'       // march, low and heavy
  | 'valley'         // drone
  | 'vanity'         // fast jig, a bit too much
  | 'despair'        // drone
  | 'mountains'      // pastoral
  | 'celestial'      // finale: full, bright, bells
  | 'tension'        // generic tension bed (arrows, chases)
  | 'title';         // title screen arrangement of the pilgrim theme

/** Music crossfades by state (GDD 2.13). Songs mark which tracks play in which states. */
export type MusicState = 'calm' | 'tension' | 'sad' | 'boss' | 'joy';

export type InstrumentId =
  | 'pluck' | 'pad' | 'bell' | 'flute' | 'bass' | 'marimba' | 'drums' | 'choir' | 'musicbox' | 'strings';

/** Babble voice per character (stored in content/characters/recipes.json as `voice`). */
export interface VoiceParams {
  /** Base pitch multiplier, ~0.5 (giant) .. 2 (child). 1 = mid adult. */
  pitch: number;
  /** Syllable rate multiplier, 1 = normal. */
  speed: number;
  wave: 'sine' | 'triangle' | 'square' | 'sawtooth';
  /** Vowel/formant colour 0..1 (0 = dark "oo", 1 = bright "ee"). */
  vowel: number;
}

export type Mood = 'neutral' | 'sad' | 'excited' | 'scared' | 'angry' | 'sleepy';

export type Vec3 = [number, number, number];

/** Song data format (content/music/themes.ts). */
export interface SongDef {
  id: SongId;
  title: string;
  bpm: number;
  /** Time signature, e.g. [4, 4] or [3, 4]. One beat = one denominator note. */
  meter: [number, number];
  /** Loop length in bars. Every track's notes must add up to exactly loopBars bars. */
  loopBars: number;
  /** Optional musical key for reference/tests, e.g. 'D major'. */
  key?: string;
  tracks: TrackDef[];
}

export interface TrackDef {
  name: string;
  instrument: InstrumentId;
  layer: 'bed' | 'melody' | 'counter' | 'bass' | 'perc' | 'sparkle';
  /** 0..1, default 0.7. */
  gain?: number;
  /**
   * Note string: space-separated tokens `PITCH:BEATS[:VEL]`. PITCH is scientific notation (C4, F#3, Bb5) or `.`
   * for a rest; for drums use K (kick), S (snare), H (hat), O (open hat), T (tom), R (rim). BEATS may be a
   * fraction (0.5, 1.5, 0.25). VEL 0..1, default 0.8. `|` bar lines are ignored but validated in dev builds.
   * Chords: join pitches with `+` (e.g. `D3+F#3+A3:4`).
   */
  notes: string;
  /** States in which this track is audible. Default: all states. */
  states?: MusicState[];
}

/** Events gameplay code emits. The audio engine subscribes (declared into EventMap in src/audio/events.ts). */
export interface AudioEventMap {
  'sfx': { id: SfxId; at?: Vec3; volume?: number; pitch?: number };
  'music:play': { id: SongId; fade?: number; state?: MusicState };
  'music:state': { state: MusicState; fade?: number };
  'music:stop': { fade?: number };
  /** Silence everything except effects for `seconds` (the Cross: 1.5 s of silence before the theme). */
  'music:silence': { fade?: number };
  'ambience:set': { id: AmbienceId | null; fade?: number };
  /** Dialogue ducks music by 6 dB while active (GDD 2.13). */
  'audio:duck': { on: boolean };
}
